--
-- Table structure for table `sys_api_token`
--

DROP TABLE IF EXISTS `sys_api_token`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_api_token` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL DEFAULT '0' COMMENT '用户ID',
  `token_name` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '令牌名称',
  `token_value` longtext COLLATE utf8mb4_general_ci COMMENT '令牌值',
  `expire_time` datetime(6) DEFAULT NULL COMMENT '过期时间',
  `last_used_time` datetime(6) DEFAULT NULL COMMENT '最后使用时间',
