DROP TABLE IF EXISTS `sys_operation_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_operation_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `username` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户名',
  `module` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '模块',
  `operation` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作',
  `method` longtext COLLATE utf8mb4_general_ci COMMENT '请求方法',
  `params` longtext COLLATE utf8mb4_general_ci COMMENT '请求参数',
  `result` longtext COLLATE utf8mb4_general_ci COMMENT '结果',
  `before_data` longtext COLLATE utf8mb4_general_ci COMMENT '变更前数据',
  `after_data` longtext COLLATE utf8mb4_general_ci COMMENT '变更后数据',
  `ip` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'IP地址',
  `operation_time` datetime(6) DEFAULT NULL COMMENT '操作时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1360 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='系统操作日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

