DROP TABLE IF EXISTS `sys_permission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_permission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint DEFAULT NULL COMMENT '父级ID',
  `perm_name` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '权限名称',
  `perm_key` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '权限标识',
  `perm_type` bigint DEFAULT NULL COMMENT '权限类型',
  `perm_group` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '权限分组',
  `resource_path` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '资源路径',
  `sort_order` bigint DEFAULT NULL COMMENT '排序号',
  `create_time` datetime(6) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='权限/菜单表';
/*!40101 SET character_set_client = @saved_cs_client */;

