--
-- Table structure for table `t_customer`
--

DROP TABLE IF EXISTS `t_customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_customer` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `cust_no` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户编号',
  `cust_name` varchar(512) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客户名称',
  `credit_code` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '统一社会信用代码',
  `contact` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人',
  `tel` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `invoice_title` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发票抬头',
  `tax_no` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '税号',
  `qual_file_id` bigint DEFAULT NULL COMMENT '资质文件ID',
  `status` bigint DEFAULT '1' COMMENT '客户状态',
  `create_time` datetime(6) DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  `city` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所在城市',
  `address` longtext COLLATE utf8mb4_general_ci COMMENT '详细地址',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_customer_unique` (`cust_name`(255),`credit_code`(255))
) ENGINE=InnoDB AUTO_INCREMENT=119 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='委托客户表';
/*!40101 SET character_set_client = @saved_cs_client */;

