--
-- Table structure for table `t_data_dict`
--

DROP TABLE IF EXISTS `t_data_dict`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_data_dict` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `dict_type` varchar(512) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '字典类型',
  `dict_label` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '字典标签',
  `dict_value` longtext COLLATE utf8mb4_general_ci COMMENT '字典值',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `status` bigint DEFAULT '1' COMMENT '状态',
  `remark` longtext COLLATE utf8mb4_general_ci COMMENT '备注',
  `create_time` datetime(6) DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_data_dict_type` (`dict_type`(255))
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='业务数据字典表';
