INSERT INTO `t_sample_param_config` (`id`, `type`, `item`, `standard`, `limit_value`, `remark`, `create_time`, `update_time`, `unit`, `inner_limit`) VALUES (3,'有组织废气','颗粒物','GB 16297-1996','颗粒物最高允许排放浓度按排气筒高度执行对应限值；低于 20mg/m³ 采用 HJ 836 低浓度法','等速采样；使用玻璃纤维滤筒；采样断面优先选在垂直管段','2026-08-05 21:08:17.463290','2026-08-05 21:08:17.463290','mg/m³','≤ 15 mg/m³（严于国标 20）'),(4,'有组织废气','二氧化硫(SO2)','GB 16297-1996','按排气筒高度执行对应排放浓度限值','使用多孔玻板吸收管；采样后避光冷藏','2026-08-05 21:08:17.473686','2026-08-05 21:08:17.473686','mg/m³','≤ 40 mg/m³（严于国标 50）'),(5,'有组织废气','氮氧化物(NOx)','GB 16297-1996','按排气筒高度执行对应排放浓度限值','使用氧化瓶+吸收液；采样后避光','2026-08-05 21:08:17.476686','2026-08-05 21:08:17.476686','mg/m³','≤ 120 mg/m³（严于国标 150）'),(6,'有组织废气','油烟','GB 18483-2002','饮食业单位油烟最高允许排放浓度 2.0 mg/m³','等速采样；使用金属滤筒；按基准风量折算','2026-08-05 21:08:17.481685','2026-08-05 21:08:17.481685','mg/m³','≤ 1.5 mg/m³（严于国标 2.0）'),(7,'无组织废气','总悬浮颗粒物(TSP)','GB 16297-1996','无组织排放监控浓度限值 1.0 mg/m³（周界外浓度最高点）','中流量采样器；采样头距地 1.5m；避免风口','2026-08-05 21:08:17.483952','2026-08-05 21:08:17.483952','mg/m³','≤ 0.8 mg/m³（严于国标 1.0）'),(8,'无组织废气','苯系物','HJ 584-2010','按标准执行对应限值','活性炭吸附管采样；采样后密封避光冷藏','2026-08-05 21:08:17.485150','2026-08-05 21:08:17.485150','mg/m³','按内控标准从严执行'),(9,'废水/地表水','化学需氧量(COD)','HJ 828-2017','按 GB 8978 污水综合排放标准执行对应限值','硫酸调 pH≤2 固定；棕色玻璃瓶；冷藏','2026-08-05 21:08:17.487617','2026-08-05 21:08:17.487617','mg/L','≤ 50 mg/L（严于国标 60）'),(10,'废水/地表水','氨氮','HJ 535-2009','按 GB 8978 执行对应限值','现场过滤；硫酸调 pH≤2；冷藏保存','2026-08-05 21:08:17.490110','2026-08-05 21:08:17.490110','mg/L','≤ 5 mg/L（严于国标 8）'),(11,'废水/地表水','总磷','GB 11893-89','按 GB 8978 执行对应限值','硫酸调 pH≤2；冷藏；聚乙烯瓶','2026-08-05 21:08:17.492552','2026-08-05 21:08:17.492552','mg/L','≤ 0.5 mg/L'),(12,'废水/地表水','总氮','HJ 636-2012','按 GB 8978 执行对应限值','硫酸调 pH≤2；避光冷藏','2026-08-05 21:08:17.494551','2026-08-05 21:08:17.494551','mg/L','≤ 15 mg/L'),(13,'废水/地表水','石油类','HJ 637-2018','按 GB 8978 执行对应限值','采样瓶必须全满、单独采样、禁止预先用水样冲洗；现场萃取或 4℃ 冷藏 24h 内萃取','2026-08-05 21:08:17.496553','2026-08-05 21:08:17.496553','mg/L','≤ 3 mg/L（严于国标 5）'),(14,'废水/地表水','挥发酚','HJ 503-2009','按 GB 8978 执行对应限值','加磷酸调 pH≤4；加 CuSO4 抑制微生物；冷藏','2026-08-05 21:08:17.499153','2026-08-05 21:08:17.499153','mg/L','≤ 0.3 mg/L'),(15,'地下水','pH','GB/T 14848-2017','地下水质量标准 Ⅰ~Ⅴ 类 pH 限值 6.5~8.5','现场测定；采样前静置；聚乙烯瓶','2026-08-05 21:08:17.502151','2026-08-05 21:08:17.502151','无量纲','6.5 ~ 8.5（内控）'),(16,'地下水','总铅','HJ 700-2014','按 GB/T 14848 各类限值执行','硝酸酸化至 pH≤2；冷藏；聚乙烯瓶','2026-08-05 21:08:17.503191','2026-08-05 21:08:17.503191','mg/L','≤ 0.05 mg/L（严于国标 0.1）'),(17,'土壤','重金属','GB 15618-2018','农用地土壤污染风险筛选值/管制值按 pH 分档','四分法缩分；风干过筛；记录采样层位','2026-08-05 21:08:17.504444','2026-08-05 21:08:17.504444','mg/kg','按内控筛选值从严'),(18,'土壤','挥发性有机物(VOCs)','HJ 605-2011','按 GB 36600 建设用地标准执行','使用 VOC 专用采样瓶；少扰动；满瓶密封；4℃ 冷藏避光','2026-08-05 21:08:17.506658','2026-08-05 21:08:17.506658','mg/kg','按内控筛选值从严'),(19,'厂界噪声','等效A声级','GB 12348-2008','昼间 60dB(A) / 夜间 50dB(A)（2 类声环境功能区）按功能区类别执行','传声器距地面 1.2m；避开反射面；同时测背景噪声','2026-08-05 21:08:17.511517','2026-08-05 21:08:17.511517','dB(A)','昼间 ≤ 55 dB(A)（内控）'),(20,'室内空气','甲醛','GB/T 18883-2022','1 小时平均浓度限值 0.08 mg/m³','采样前关闭门窗 12h；大型气泡吸收管；室温记录','2026-08-05 21:08:17.514070','2026-08-05 21:08:17.514070','mg/m³','≤ 0.08 mg/m³（严于国标 0.10）'),(21,'室内空气','苯、甲苯、二甲苯','HJ 583-2010','1 小时平均限值 苯 0.11 / 甲苯 0.20 / 二甲苯 0.20 mg/m³','Tenax TA 吸附管；采样前封闭 12h；记录温湿度','2026-08-05 21:08:17.516080','2026-08-05 21:08:17.516080','mg/m³','≤ 0.06 mg/m³（内控）'),(22,'固体废物','浸出液重金属','GB 5085.3-2007','浸出毒性鉴别标准按项目分别执行','硫酸硝酸法浸提；转速 30r/min；浸提 18h；测 pH','2026-08-05 21:08:17.517081','2026-08-08 00:32:30.306362','mg/L','按内控鉴别值从严');
/*!40000 ALTER TABLE `t_sample_param_config` ENABLE KEYS */;
UNLOCK TABLES;

