CREATE TABLE `wf_process_instance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `instance_no` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实例编号',
  `process_key` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程标识',
  `process_name` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程名称',
  `process_version` bigint DEFAULT NULL COMMENT '流程版本',
  `business_key` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务键',
  `status` bigint DEFAULT NULL COMMENT '实例状态',
  `current_node_id` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '当前节点ID',
  `start_user` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发起人',
  `start_time` datetime(6) DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(6) DEFAULT NULL COMMENT '结束时间',
  `duration` bigint DEFAULT NULL COMMENT '耗时(毫秒)',
  `version` bigint DEFAULT '0' COMMENT '版本号',
  `create_time` datetime(6) DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程实例表';
