  `process_key` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程标识',
  `node_id` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '节点ID',
  `node_name` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '节点名称',
  `task_type` bigint DEFAULT NULL COMMENT '任务类型',
  `assignee` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '办理人',
  `candidate_users` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '候选办理人(逗号分隔)',
  `claim_time` datetime(6) DEFAULT NULL COMMENT '签收时间',
  `complete_time` datetime(6) DEFAULT NULL COMMENT '完成时间',
  `task_action` bigint DEFAULT '0' COMMENT '任务操作',
  `status` bigint DEFAULT NULL COMMENT '任务状态',
  `counter_sign_group_id` bigint DEFAULT NULL COMMENT '会签组ID',
  `add_sign_type` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '加签类型',
  `sign_type` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '加签类型',
  `parent_task_id` bigint DEFAULT NULL COMMENT '父任务ID',
  `reason` longtext COLLATE utf8mb4_general_ci COMMENT '原因',
  `actual_operator_id` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实际操作人ID',
  `create_time` datetime(6) DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程任务表';
