--
-- Table structure for table `wf_webhook`
--

DROP TABLE IF EXISTS `wf_webhook`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_webhook` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `webhook_key` varchar(512) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'Webhook标识',
  `name` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Webhook名称',
  `url` varchar(512) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'URL',
  `method` longtext COLLATE utf8mb4_general_ci COMMENT 'HTTP请求方法',
  `headers` longtext COLLATE utf8mb4_general_ci COMMENT '请求头(JSON)',
  `payload_template` longtext COLLATE utf8mb4_general_ci COMMENT '请求体模板',
  `timeout` bigint DEFAULT '5000' COMMENT '超时时间(毫秒)',
  `retry_count` bigint DEFAULT '3' COMMENT '重试次数',
  `trigger_events` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '触发事件(逗号分隔)',
  `process_key` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程标识',
  `node_id` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '节点ID',
  `status` bigint DEFAULT '1' COMMENT 'Webhook状态',
  `create_time` datetime(6) DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_webhook_key` (`webhook_key`(255))
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Webhook回调配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

