--
-- Table structure for table `wf_webhook_log`
--

DROP TABLE IF EXISTS `wf_webhook_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_webhook_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `webhook_id` bigint DEFAULT NULL COMMENT 'Webhook ID',
  `webhook_key` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Webhook标识',
  `event_type` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '事件类型',
  `process_instance_id` bigint DEFAULT NULL COMMENT '流程实例ID',
  `request_url` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求地址',
  `request_method` longtext COLLATE utf8mb4_general_ci COMMENT '请求方法',
  `request_body` longtext COLLATE utf8mb4_general_ci COMMENT '请求体',
  `response_status` bigint DEFAULT NULL COMMENT '响应状态码',
  `response_body` longtext COLLATE utf8mb4_general_ci COMMENT '响应体',
  `status` bigint DEFAULT '0' COMMENT '状态',
  `retry_count` bigint DEFAULT '0' COMMENT '重试次数',
  `error_message` longtext COLLATE utf8mb4_general_ci COMMENT '错误信息',
  `trigger_time` datetime(6) DEFAULT NULL COMMENT '触发时间',
  `complete_time` datetime(6) DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Webhook调用日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

